<?php require 'includes/bootstrap.php';require_role('admin');if($_SERVER['REQUEST_METHOD']!=='POST')go('admin_dashboard.php');$kind=($_POST['kind']??'')==='faculty'?'faculty':'student';$ids=array_map('intval',$_POST['ids']??[]);$action=$_POST['action']??'';if(!$ids){flash('Select at least one request.');go('admin_'.$kind.'_requests.php');}$marks=implode(',',array_fill(0,count($ids),'?'));if($action==='approve'){$q=$pdo->prepare("UPDATE $kind SET is_approved=1 WHERE id IN ($marks)");$q->execute($ids);flash('Selected accounts approved.');}elseif($action==='reject'){$q=$pdo->prepare("DELETE FROM $kind WHERE id IN ($marks)");$q->execute($ids);flash('Selected requests rejected.');}go('admin_'.$kind.'_requests.php');?>
